import sys, os, re, json, mimetypes, subprocess, urllib.parse, shlex

XDG_CONFIG_HOME = os.environ.get("XDG_CONFIG_HOME", os.path.expanduser("~/.config"))
XDG_DATA_HOME = os.environ.get("XDG_DATA_HOME", os.path.expanduser("~/.local/share"))
XDG_DATA_DIRS = os.environ.get("XDG_DATA_DIRS", "/usr/local/share:/usr/share")
MIMEAPPS_PATH = os.path.join(XDG_CONFIG_HOME, "mimeapps.list")

def get_app_dirs():
    dirs = [XDG_DATA_HOME] + XDG_DATA_DIRS.split(":")
    return [os.path.join(d, "applications") for d in dirs]

def parse_desktop(path):
    entry = {}
    try:
        with open(path, 'r', encoding='utf-8') as f:
            lines = f.readlines()
        in_entry = False
        for line in lines:
            line = line.strip()
            if line == '[Desktop Entry]':
                in_entry = True
                continue
            if line.startswith('[') and line.endswith(']'):
                in_entry = False
            if in_entry and '=' in line:
                k, v = line.split('=', 1)
                entry[k] = v
        if 'Name' in entry: # Basic validation
            return entry
    except:
        pass
    return None

def get_all_desktops():
    desktops = {}
    for d in reversed(get_app_dirs()):
        if not os.path.isdir(d): continue
        for f in os.listdir(d):
            if f.endswith('.desktop'):
                path = os.path.join(d, f)
                parsed = parse_desktop(path)
                if parsed:
                    desktops[f] = parsed
    return desktops

def load_mimeapps():
    if not os.path.exists(MIMEAPPS_PATH):
        return {}
    defaults = {}
    in_default = False
    with open(MIMEAPPS_PATH, 'r') as f:
        for line in f:
            line = line.strip()
            if line == '[Default Applications]':
                in_default = True
            elif line.startswith('['):
                in_default = False
            elif in_default and '=' in line:
                k, v = line.split('=', 1)
                defaults[k] = [x for x in v.split(';') if x]
    return defaults

def save_mimeapps(defaults):
    os.makedirs(XDG_CONFIG_HOME, exist_ok=True)
    with open(MIMEAPPS_PATH, 'w') as f:
        f.write("[Added Associations]\n\n[Default Applications]\n")
        for k in sorted(defaults.keys()):
            v = ";".join(defaults[k])
            if v:
                f.write(f"{k}={v};\n")
EOF"}

