{"command":"cat <<'EOF' >> handlr.py

def list_cmd(all=False):
    desktops = get_all_desktops()
    defaults = load_mimeapps()

    # Clean defaults
    cleaned_defaults = {}
    for k, v in defaults.items():
        valid_apps = [app for app in v if app in desktops]
        if valid_apps:
            cleaned_defaults[k] = valid_apps
    save_mimeapps(cleaned_defaults)

    def draw_table(rows):
        if not rows:
            print("┌──┐\n│  │\n└──┘")
            return
        col1_len = max(len(r[0]) for r in rows)
        col2_len = max(len(r[1]) for r in rows)
        print(f"┌{'─' * (col1_len + 2)}┬{'─' * (col2_len + 2)}┐")
        for r in rows:
            print(f"│ {r[0].ljust(col1_len)} │ {r[1].ljust(col2_len)} │")
        print(f"└{'─' * (col1_len + 2)}┴{'─' * (col2_len + 2)}┘")

    rows = []
    for k in sorted(cleaned_defaults.keys()):
        rows.append((k, cleaned_defaults[k][0]))

    if all:
        print("Default Apps")
    draw_table(rows)

    if all:
        print("System Apps")
        sys_apps = {}
        for d in get_app_dirs():
            if not os.path.isdir(d): continue
            for f in os.listdir(d):
                if f.endswith('.desktop') and f in desktops:
                    mimes = desktops[f].get('MimeType', '').split(';')
                    for m in mimes:
                        if m:
                            sys_apps.setdefault(m, []).append(f)
        s_rows = []
        for k in sorted(sys_apps.keys()):
            s_rows.append((k, ", ".join(sys_apps[k])))
        draw_table(s_rows)

def print_help(cmd):
    if cmd == "main":
        print("""handlr 0.6.4

USAGE:
    executable <SUBCOMMAND>

FLAGS:
    -h, --help       Prints help information
    -V, --version    Prints version information

SUBCOMMANDS:
