import shlex
def clean_cmd(exec_str):
    for pat in ['%f', '%F', '%u', '%U', '%i', '%c', '%k']:
        exec_str = exec_str.replace(pat, '')
    parts = shlex.split(exec_str)
    return ' '.join(parts)

